\label{Ccomponent}
A compact connected Riemannian $3$-manifold $(M,g)$ is a
\emph{$C$-component} if:
\begin{enumerate}
\item[(1)] $M$ is diffeomorphic to $S^3$ or $\Ar P^3$;
\item[(2)] $M$ has positive sectional curvature;
\item[(3)]
\[
 C^{-1}<\frac{\inf_PK(P)}{\sup_MR};
\]
\item[(4)]
\[
 C^{-1}\sup_MR^{-1/2}<\diam M<C\inf_MR^{-1/2}.
\]
\end{enumerate}
\end{definition}

